CREATE COLUMN TABLE "TEST_AP"."OCST" ("Code" NVARCHAR(3) NOT NULL , "Country" NVARCHAR(3) NOT NULL , "Name" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "eCode" SMALLINT CS_INT, "GNRECode" NVARCHAR(4), "GSTCode" NVARCHAR(2), "GSTIsUT" NVARCHAR(1) DEFAULT 'N', "GroupCode" SMALLINT CS_INT, PRIMARY KEY ("Country", "Code")) UNLOAD PRIORITY 0  AUTO MERGE ;
ALTER TABLE "TEST_AP"."OCST" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$GSTCode$Country$','GSTCode','Country'));
CREATE INDEX "OCST_GST_CODE" ON "TEST_AP"."OCST" ( "GSTCode" ASC, "Country" ASC )